sn_aia_tool.script:
(function(inputs) {
    // only string inputs are allowed 
    // return outputs object where the keys in it are understandable by LLM  
    var result = '';
    var number = inputs.incident_number;

    if (gs.nil(number))
        return gs.getMessage('No incident number provided.');

    var incidentGR = new GlideRecord("incident");
    incidentGR.addEncodedQuery('number=' + number + '^ORsys_id=' + number);
    incidentGR.query();

    if (!incidentGR.next())
        return gs.getMessage('Cannot find an incident with the given incident number.');

    result += "Incident Number: " + incidentGR.getValue('number') + "\n\n";
    result += "Incident sysID: " + incidentGR.getValue('sys_id') + "\n\n";
    result += "Short Description: " + incidentGR.getValue('short_description') + "\n\n";
    result += "Description: " + incidentGR.getValue('description') + "\n\n";

    return result;
})(inputs);
